%   dy_dx0 = dy_dz + dy_dz_conj
%   dy_dx1 = 1j * (dy_dz - dy_dz_conj)
%   J = [[Re(dy_dx0), Re(dy_dx1)],
%        [Im(dy_dx0), Im(dy_dx1)]]
dy_dx0 = dy_dz + dy_dz_conj;
dy_dx1 = 1j .* (dy_dz - dy_dz_conj);

N = numel(dy_dx0);
J = zeros(2, 2, N);
J(1, 1, :) = real(dy_dx0);
J(1, 2, :) = real(dy_dx1);
J(2, 1, :) = imag(dy_dx0);
J(2, 2, :) = imag(dy_dx1);

end
